"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[71010],{71010:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/the-11-character-killing.png\\"\\n          title=\\"The 11-Character Murder\\"\\n          author=\\"Keigo Higashino\\"\\n          publisher=\\"Random House Korea\\"\\n          publishedDate=\\"2007-08-04\\"\\n          isbn=\\"9788925511238\\"\\n          rating=3.5\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\nThe entire work seems to be constructed based on the theme: ```There is not a single good person in this murder```.  \\nThe author does not apply an absolute yardstick of good or evil to any of the characters.  \\nThis would be a more realistic character setting.  \\n<br>\\nInstead of asking ```who is the worst```, it gives a fundamental moral dilemma of <mark>what is true justice</mark>.  \\n<br>\\nBy narrating with alternating perspectives of the protagonist and the culprit, one can better feel the agony and determination within the culprit\'s heart.  \\n<br>\\nFor me, the culprit\'s motive is somewhat difficult to understand.  "}')}}]);